import { useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { FROM_GAMES, GAMES_PATH } from './data.js';

/**
 * Leaving a mode (the close control, Escape, Back to games). Opened from the
 * games screen, it pops the history, so the games screen is where it was
 * and Back does not reopen the game; opened any other way (a link, a
 * notification), it goes to the games screen.
 */
export function useLeaveMode(): () => void {
  const navigate = useNavigate();
  const location = useLocation();
  const state: unknown = location.state;
  const fromGames =
    typeof state === 'object' &&
    state !== null &&
    (state as { fromGames?: unknown }).fromGames === FROM_GAMES.fromGames;
  return useCallback(() => {
    if (fromGames) void navigate(-1);
    else void navigate(GAMES_PATH);
  }, [fromGames, navigate]);
}
